end
function U.secsTo(ou,pu,qu,ru,su)
if ou>=pu then
return 0
end
local tu,uu=0,ou
local vu=I.P.LevelFor(uu,qu,ru)
local wu=I.P.LevelCap(qu,ru)
for xu=1,600 do
local yu=I.T.BasicRate(vu,qu,ru)*su
if yu<=0 then
return x.BIG*60
end
local zu=(vu>=wu)and pu or math.min(pu,I.P.VenomFor(vu+1,qu))
tu=tu+math.max(0,zu-uu)/yu
uu=zu
if uu>=pu then
break
end
vu=vu+1
end
return tu
end
function U.listedWins(Au)
local Bu=I.S.List[Au]
return(Bu and Bu.wins or 0)*I.winsMult()
end
function U.winsPer(Cu)
local Du=1
pcall(function()
Du=Du*I.R.PotionMultiplier(u,mD[255])
end)
pcall(function()
Du=Du*I.Ev.Multiplier(mD[255])
end)
local Eu=z.stages[mD[342]..Cu]
local Fu=(type(Eu)==mD[199]and tonumber(Eu.winsK))or 1
return U.listedWins(Cu)*Du*Fu
end
function U.pwin(Gu,Hu)
local Iu=I.S.List[Gu]
if not Iu then
return 0
end
local Ju=Hu/math.max(1e-9,Iu.need/I.Bal.StageUnit)
local Ku=z.stages[mD[342]..Gu]
local Lu=type(Ku)==mD[199]and tonumber(Ku.bossWall)
if Lu and Ju<Lu*0.8 then
return 0.02
end
if y.instantKill and y.instantAll then
return 0.97
end
local Mu=H.lerp({{0.5,0.02},{0.6,0.1},{0.7,0.3},{0.85,0.62},{1.0,0.9},{1.3,0.98}},Ju)
local Nu=z.stages[mD[342]..Gu]
if type(Nu)~=mD[199]or type(Nu.res)~=mD[199]or#Nu.res==0 then
return Mu
end
local Ou,Pu=0,0
for Qu,Ru in ipairs(Nu.res)do
local Su,Tu=tonumber(Ru[1]),tonumber(Ru[2])
if Su and Tu and Su>0 then
local Uu=math.exp(-math.abs(math.log(Ju/Su))*4)
if Tu==1 and Su<=Ju then
Uu=1
end
if Tu==0 and Su>=Ju then
Uu=1
end
Ou=Ou+Uu
Pu=Pu+Uu*Tu
end
end
return(Pu+Mu*2)/(Ou+2)
end
function U.guessSecs(Vu)
local Wu=I.E.Stages[Vu]or{}
local Xu=0
for Yu,Zu in pairs(Wu.mix or{})do
Xu=Xu+Zu
end
Xu=Xu*math.max(1,Wu.waves or 1)
return 15+Xu*4+(Wu.boss and 35 or 0)+(Wu.mini and 20 or 0)
end
function U.guessK()
