function U.fightPlan(jv,kv,lv,mv)
local nv=math.max(0,jv.needWins-mv)
local ov,pv=I.P.WorldGate(jv.evo,lv,I.Maps.Live)
if nv<=0 and not ov then
return 0,nil
end
local qv
local rv,sv=0,0
for tv=1,x.MAX_STAGE do
if I.Maps.WorldOfStage(tv)>(y.worlds and x.MAX_WORLD or 1)then
break
end
local uv=U.pwin(tv,kv)
if uv<y.minWin then
break
end
if tv>lv then
rv=rv+U.clearMin(tv)/uv
sv=sv+U.winsPer(tv)
end
local vv=math.max(0,nv-sv)
local wv=math.max(1e-9,U.winsPer(tv))
local xv=math.ceil(vv/wv)
local yv=rv+xv*U.replayMin(tv)/uv
if ov and math.max(lv,tv)<(pv or 0)then
yv=x.BIG
end
if not qv or yv<qv.mins then
qv={mins=yv,t=tv,reps=xv}
end
end
if not qv then
return x.BIG,nil
end
return math.min(qv.mins,x.BIG),qv
end
function U.fightVenom(zv,Av)
